{
  "summary": "The paper introduces PelviNeXt, a modality-agnostic hybrid network designed for pelvic imaging in women's health, evaluated on PCOS ultrasound and pelvic fracture X-ray datasets. The authors identify and audit extensive duplicate contamination in the PCOSGen dataset, releasing a deduplicated version. PelviNeXt achieves state-of-the-art results on both tasks, outperforming standard CNN and transformer baselines.",
  "items": {
    "chk_problem": {
      "value": "Scarcity of public, well-annotated benchmark data for pelvic pathologies in women's health, such as PCOS and pelvic fracture.",
      "paper_quote": "Women’s health remains substantially under-resourced in medical imaging research, with pelvic pathologies such as polycystic ovary syndrome (PCOS) and pelvic fracture both suffering from a scarcity of public, well-annotated benchmark data despite their clinical importance."
    },
    "chk_method": {
      "value": "PelviNeXt, a modality-agnostic hybrid architecture combining a dense convolutional feature extractor, hierarchical channel-spatial attention, a multi-scale fusion module, and talking-heads self-attention.",
      "paper_quote": "We introduce PelviNeXt, a modality-agnostic hybrid architecture combining a dense convolutional feature extractor, hierarchical channel-spatial attention (H-CBAM), a multi-scale fusion module (MSFM), and talking-heads multi-head self-attention (TH-MHSA), applied without modification to both pelvic ultrasound and X-ray inputs."
    },
    "chk_data": {
      "value": "The deduplicated PCOSGen ultrasound dataset containing 225 images and the PXR150 pelvic fracture X-ray dataset containing 150 radiographs.",
      "paper_quote": "The original pool of 4,668 images reduces to 225 (63 Normal, 162 Abnormal), a 95.2% reduction."
    },
    "chk_setup": {
      "value": "Models are trained from scratch using AdamW, batch size 16, for 30 epochs, under 5-fold stratified cross-validation with class-aware data augmentation.",
      "paper_quote": "All models are trained from scratch using AdamW (lr = 1×10−4 , cosine annealing), batch size 16, for 30 epochs, under 5-fold stratified cross-validation with augmentation applied only to training folds."
    },
    "chk_primary_result": {
      "value": "PelviNeXt achieved 87.33% accuracy, 89.00% recall, 87.00% specificity, and 0.8920 AUROC on PXR150, and 92.00% accuracy and 0.9051 AUROC on the deduplicated PCOSGen dataset.",
      "paper_quote": "PelviNeXt achieves the highest accuracy (87.33%, ±2.45), recall (89.00%, ±5.71), specificity (87.00%, ±3.92), and AUROC (0.8920, ±0.0288) among all methods, exceeding the strongest prior result, Patch Ensemble [2] (84.00% accuracy, 87.00% recall, 82.00% specificity, 0.8700 AUROC), across every reported metric."
    },
    "chk_secondary_result": {
      "value": "Ablation studies showed that removing the Multi-Scale Fusion Module (MSFM) caused the largest AUROC drop on both PCOS (0.9051 to 0.8735) and pelvic fracture (0.8920 to 0.8576) tasks.",
      "paper_quote": "Removing MSFM causes the largest AUROC drop on both tasks (PCOS: 0.9051 → 0.8735; fracture: 0.8920 → 0.8576), identifying multi-scale fusion as the most critical component for global discriminative performance."
    },
    "chk_baseline": {
      "value": "Standard architectures ViT-B/16, ResNet-101, and DenseNet-169, as well as prior pelvic fracture models like Patch Ensemble.",
      "paper_quote": "PelviNeXt achieves the highest performance across all five metrics, with a mean accuracy of 92.00% (±1.60) and AUROC of 0.9051 (±0.0156), outperforming ViT-B/16 [5], ResNet-101 [9], and DenseNet-169 [10] by at least 2.67 percentage points in accuracy and 0.0422 in AUROC."
    },
    "chk_conclusion": {
      "value": "PelviNeXt serves as a reliable, modality-agnostic foundation for pelvic imaging across ultrasound and X-ray modalities in data-scarce areas of women's health.",
      "paper_quote": "Our results demonstrate that a single architecture, applied without task-specific modification, can serve as a reliable foundation for pelvic imaging across modalities in data-scarce, under-researched areas of women’s health."
    },
    "chk_limitation": {
      "value": "The small size of both datasets (225 images for PCOS and 150 images for PXR150), which limits statistical power.",
      "paper_quote": "A limitation of this work is the small size of both datasets: the deduplicated PCOS dataset contains 225 images and PXR150 contains 150 images, which limits statistical power despite 5-fold CV with 95% CIs."
    }
  }
}
